<?php
declare(strict_types=1);
require_once __DIR__ . '/../functions/helpers.php';
require_role('admin');

$products = db()->query('SELECT p.id,p.name,p.description,p.price,p.stock,p.image,p.is_active,c.name AS category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.id DESC')->fetchAll();
$categories = db()->query('SELECT id,name FROM categories WHERE is_active=1 ORDER BY name')->fetchAll();
$orderCount = (int) db()->query('SELECT COUNT(*) FROM orders')->fetchColumn();
$userCount = (int) db()->query("SELECT COUNT(*) FROM users WHERE role = 'customer'")->fetchColumn();
$revenue = (float) db()->query("SELECT COALESCE(SUM(total_amount),0) FROM orders WHERE status <> 'cancelled'")->fetchColumn();
$flash = get_flash();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Admin Dashboard | Gonzaga's Apparel</title><link rel="stylesheet" href="../css/style.css"><link rel="stylesheet" href="../css/admin.css"></head>
<body class="admin-page"><header class="admin-header"><a href="../index.php"><img src="../assets/images/logo-placeholder.svg" alt="Gonzaga's Apparel"></a><div><span>ADMIN: <?= e($_SESSION['name'] ?? '') ?></span><form action="../logout.php" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><button type="submit">LOG OUT</button></form></div></header><main class="admin-shell"><div class="section-kicker">MANAGEMENT <span></span></div><h1>ADMIN DASHBOARD</h1><?php if ($flash): ?><div class="alert <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><div class="stats"><div><strong><?= $userCount ?></strong><span>CUSTOMERS</span></div><div><strong><?= $orderCount ?></strong><span>ORDERS</span></div><div><strong><?= money($revenue) ?></strong><span>REVENUE</span></div></div><section class="admin-card"><div class="admin-card-head"><h2>PRODUCTS</h2><div class="admin-card-actions"><a class="button button--outline" href="orders.php">MANAGE ORDERS</a><a class="button button--filled" href="product_create.php">ADD PRODUCT</a></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>PRODUCT</th><th>CATEGORY</th><th>PRICE</th><th>STOCK</th><th>ACTIVE</th><th>ACTIONS</th></tr></thead><tbody><?php foreach ($products as $product): ?><tr><td><?= (int)$product['id'] ?></td><td><strong><?= e($product['name']) ?></strong><small><?= e($product['image']) ?></small></td><td><?= e($product['category_name'] ?? 'Uncategorized') ?></td><td><?= money((float)$product['price']) ?></td><td><?= (int)$product['stock'] ?></td><td><?= $product['is_active'] ? 'YES' : 'NO' ?></td><td class="actions"><a href="product_edit.php?id=<?= (int)$product['id'] ?>">EDIT</a><form action="product_delete.php" method="post" onsubmit="return confirm('Delete this product?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$product['id'] ?>"><button type="submit">DELETE</button></form></td></tr><?php endforeach; ?></tbody></table></div></section><section class="admin-card category-manager"><div class="admin-card-head"><h2>CATEGORIES</h2></div><form class="category-form" action="category_create.php" method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input name="name" maxlength="100" placeholder="New category name" required><input name="description" maxlength="500" placeholder="Short description"><button class="button button--filled" type="submit">ADD CATEGORY</button></form><div class="category-list"><?php foreach($categories as $category): ?><span><?= e($category['name']) ?></span><?php endforeach; ?></div></section></main></body></html>
